 const alpha=await command('addTeam',{eventId:event2,name:'Alpha',color:'#72d5e3'});const bravo=await command('addTeam',{eventId:event2,name:'Bravo',color:'#83d6b2'});assert.equal(alpha.status,200);assert.equal(bravo.status,200);
